const message = $input.first().json.message || {};
const text = message.text || '';
const fromUser = message.from || {};
const chatId = message.chat ? message.chat.id : '';

const systemPrompt = `Eres un consultor y SDR experto en Inteligencia Artificial y Automatización de Negocios para la academia 'Laboratorio de Asistente IA'.\nTu misión es mantener una conversación natural, cordial, empática y persuasiva por chat para calificar al prospecto usando el marco BANT:\n- Budget (Presupuesto o capacidad de inversión)\n- Authority (Toma de decisiones en el negocio)\n- Need (Dolores operativos, necesidad de captación, automatización de ventas o soporte)\n- Timeline (Urgencia de implementación: inmediata, este mes, futuro)\n\nReglas:\n1. Responde de forma concisa (máximo 2 a 3 párrafos cortos, tono profesional y enérgico, con emojis estratégicos).\n2. Haz 1 sola pregunta clave a la vez para mantener el diálogo fluido.\n3. Si el usuario muestra alto interés y presupuesto/necesidad clara, recomiéndale agendar una sesión estratégica o unirse al programa intensivo.\n4. Devuelve SIEMPRE tu respuesta en formato JSON estricto con los siguientes campos:\n{\n  "reply_message": "Tu mensaje redactado para el usuario en Telegram con formato Markdown",\n  "need_summary": "Resumen de la necesidad del cliente o 'En exploración'",\n  "budget_range": "Bajo (<$500) | Medio ($500-$1500) | Alto (>$1500) | No especificado",\n  "authority": "Dueño/CEO | Gerente | Freelancer | Sin definir",\n  "timeline": "Inmediato | 30 días | Exploratorio",\n  "lead_score": 85, // número entre 0 y 100\n  "is_qualified": true // true si lead_score >= 70 y necesidad clara\n}`;

return [{
  json: {
    chat_id: chatId,
    user_name: fromUser.first_name || 'Usuario',
    user_handle: fromUser.username || 'sin_username',
    user_message: text,
    payload: {
      contents: [
        {
          role: "user",
          parts: [
            {
              text: `${systemPrompt}\n\n--- MENSAJE DEL USUARIO ---\nNombre: ${fromUser.first_name || ''} (@${fromUser.username || 'sin_username'})\nChat ID: ${chatId}\nMensaje actual: "${text}"`
            }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.7,
        topP: 0.95,
        responseMimeType: "application/json"
      }
    }
  }
}];

const item = $input.first().json;
const prevContext = $('Preparar Contexto BANT').first().json;

let parsedData = {
  reply_message: '¡Gracias por tu mensaje! Cuéntame más sobre tu proyecto para recomendarte la mejor arquitectura de automatización.',
  need_summary: 'En evaluación',
  budget_range: 'No especificado',
  authority: 'Sin definir',
  timeline: 'Exploratorio',
  lead_score: 50,
  is_qualified: false
};

try {
  const rawText = item.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```/g, '').trim();
  const geminiJson = JSON.parse(cleaned);
  parsedData = { ...parsedData, ...geminiJson };
} catch (error) {
  if (item.candidates?.[0]?.content?.parts?.[0]?.text) {
    parsedData.reply_message = item.candidates[0].content.parts[0].text;
  }
}

return [{
  json: {
    chat_id: prevContext.chat_id,
    user_name: prevContext.user_name,
    user_handle: prevContext.user_handle,
    user_message: prevContext.user_message,
    reply_message: parsedData.reply_message,
    need_summary: parsedData.need_summary,
    budget_range: parsedData.budget_range,
    authority: parsedData.authority,
    timeline: parsedData.timeline,
    lead_score: parsedData.lead_score,
    is_qualified: parsedData.is_qualified,
    timestamp: new Date().toISOString()
  }
}];

